        if (s.status === "fulfilled") {
          for (const x of s.value.data) {
            out.push({
              date: x.created_at,
              icon: Stethoscope,
              type: "Symptoms",
              title: x.symptoms?.slice(0, 4).join(", ") || "Symptom check",
